"""Seam coverage for the configurable composition lead-in key (upstream #525).

The 大易 address hotkeys and the cinbase 多功能前導字元 used to fight over the
backtick: the interception was hardcoded. ``leadInKey`` is now a setting — with
it remapped, the backtick is no longer intercepted and reaches the table
engine, while the new key opens the composition; the default keeps the old
behaviour.
"""

import os
import sys
import unittest

ROOT = os.path.abspath(os.path.join(os.path.dirname(__file__), os.path.pardir))
for _path in (os.path.join(ROOT, "python"), os.path.dirname(os.path.abspath(__file__))):
    if _path not in sys.path:
        sys.path.insert(0, _path)

from test_cinbase_shift_to_english import CinbaseKeyHarness  # noqa: E402

BACKTICK = 0x60
SEMICOLON = 0x3B


class CinbaseLeadInKeyTests(CinbaseKeyHarness):

    def test_default_lead_in_key_opens_the_composition(self):
        service = self.activate_chesimplex()
        self.assertEqual(service.leadInKey, "`")
        self.assertEqual(service.cfg.leadInKey, "`")

        self.send(service, BACKTICK, 0xC0)  # VK_OEM_3

        self.assertTrue(service.multifunctionmode)
        self.assertEqual(service.compositionChar, "`")
        self.assertTrue(service.filterKeyDown(
            self.key_event(BACKTICK, 0xC0)), "the lead-in key must be claimed")

    def test_remapped_lead_in_key_opens_the_composition(self):
        service = self.activate_chesimplex()
        service.cfg.leadInKey = ";"
        service.cinbase.applyConfig(service)
        self.assertEqual(service.leadInKey, ";")

        self.send(service, SEMICOLON, 0xBA)  # VK_OEM_1

        self.assertTrue(service.multifunctionmode)
        self.assertEqual(service.compositionChar, ";")

    def test_backtick_reaches_the_engine_when_lead_in_is_remapped(self):
        service = self.activate_chesimplex()
        service.cfg.leadInKey = ";"
        service.cinbase.applyConfig(service)
        self.assertFalse(service.cin.isInKeyName("`"), "setup: not a radical")

        claimed = service.filterKeyDown(self.key_event(BACKTICK, 0xC0))

        self.assertFalse(claimed, "the unused backtick must go to the application")
        self.assertFalse(service.multifunctionmode)

    def test_menu_uses_the_configured_lead_in_key(self):
        service = self.activate_chesimplex()
        service.cfg.leadInKey = ";"
        service.cinbase.applyConfig(service)

        self.send(service, SEMICOLON, 0xBA)
        self.send(service, ord("M"), 0x4D, printable=True, shift=True)

        self.assertTrue(service.showmenu, "the menu opened with the old prefix only")


if __name__ == "__main__":
    unittest.main()
